import{_ as i,C as r,o as h,c as s,j as e,a as d,E as o,a5 as c}from"./chunks/framework.CyyS6Zdm.js";const g=JSON.parse('{"title":"快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"components/hotkeys.md","filePath":"components/hotkeys.md","lastUpdated":1787185306000}'),n={name:"components/hotkeys.md"},b={id:"快捷键",tabindex:"-1"};function p(y,t,k,u,f,m){const l=r("Badge"),a=r("XhDemo");return h(),s("div",null,[e("h1",b,[t[0]||(t[0]=d("快捷键 ",-1)),o(l,{type:"info",text:"hotkeys"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#快捷键","aria-label":'Permalink to "快捷键 <Badge type="info" text="hotkeys" />"'},"​",-1))]),t[3]||(t[3]=c('<p>注册一组键盘组合，并按当前平台的写法把它显示成一排键帽。<code>Mod</code> 这个词在 Mac 上出 ⌘、其余平台出 Ctrl，同一份 <code>keys</code> 两边都对。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>给一个已有的动作再配一条键盘通路，并让用户看得见这条通路。</li><li>在菜单条目、按钮旁标出它的组合。</li><li>面板里列一张快捷键速查表。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只想把一串命令或代码原样显示出来：用<a href="./code-block">代码块</a>。</li><li>只想在悬停时说明某个按钮做什么：用<a href="./tooltip">文字提示</a>，快捷键至多是提示里的一句。</li><li>只需要一小块静态状态标记：用<a href="./badge">徽标</a>。</li><li>想在一处收口整页的方向键导航：那是<a href="./toolbar">工具条</a>、<a href="./menu">菜单</a>这类组件自己的事，不要用快捷键去顶。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>平台写法只有两套：Mac 出 ⌘ ⇧ ⌥ ⌃ 且键帽连排，其余平台出 Ctrl Shift Alt 且用加号连接。</li><li>平台默认 <code>auto</code>，由适配器挂载后测出来传进来；服务端渲染那一帧按非 Mac 出，落地后自行换成实测值。</li><li>修饰键逐个全等比对：注册了 <code>Ctrl+S</code> 时按 <code>Ctrl+Shift+S</code> 不会命中，两条组合分得开。</li><li>命中后默认拦下浏览器的默认动作，<code>preventDefault</code> 可关。</li><li>组合里除 Shift 外没有别的修饰键时，落在输入框、文本域、可编辑区里的按键一律让给输入。</li><li>输入法组合期的按键不接：那段时间的按键是给候选框用的。</li><li>键帽与连接符的内容整份归组件所有：出多少枚、每一枚写什么由 <code>keys</code> 与平台算出来，写进容器里的东西会被替换掉，也收不到插槽内容。</li><li>Web Components 的 <code>keys</code> 属性按逗号分隔，因此属性写法表达不出「逗号本身」这枚主键；<code>Mod+,</code> 这类组合改用 property 传数组。</li><li>尺寸一轴与其余组件同源。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一组组合的键帽：Mod 在 Mac 上出 ⌘、其余平台出 Ctrl，平台由组件自己测出来</p>',10)),o(a,{src:"hotkeys/01-basic"}),t[4]||(t[4]=e("h3",{id:"平台写法",tabindex:"-1"},[d("平台写法 "),e("a",{class:"header-anchor",href:"#平台写法","aria-label":'Permalink to "平台写法"'},"​")],-1)),t[5]||(t[5]=e("p",null,"同一份 keys 两套写法：Mac 出符号且键帽连排，其余平台出单词并用加号连接",-1)),o(a,{src:"hotkeys/02-platform"}),t[6]||(t[6]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[7]||(t[7]=e("p",null,"size 换的是字号与键帽的内边距，三档与其余控件同源",-1)),o(a,{src:"hotkeys/03-size"}),t[8]||(t[8]=e("h3",{id:"限定范围",tabindex:"-1"},[d("限定范围 "),e("a",{class:"header-anchor",href:"#限定范围","aria-label":'Permalink to "限定范围"'},"​")],-1)),t[9]||(t[9]=e("p",null,"target 写 parent 时只在组件所在的那一层容器里接组合，整页范围的组合不会互相抢",-1)),o(a,{src:"hotkeys/04-scoped"}),t[10]||(t[10]=e("h3",{id:"开关监听",tabindex:"-1"},[d("开关监听 "),e("a",{class:"header-anchor",href:"#开关监听","aria-label":'Permalink to "开关监听"'},"​")],-1)),t[11]||(t[11]=e("p",null,"enabled 关掉后组合不再触发，键帽也转成不可用的样子",-1)),o(a,{src:"hotkeys/05-toggle"}),t[12]||(t[12]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-hotkeys&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhHotkeys</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/hotkeys.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;hotkeys&quot;</code>：<strong><code>root</code></strong> · <code>key</code> · <code>separator</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>boolean</code></td><td></td><td>监听是否生效，缺省开启；关掉后组合不再触发，键帽也转成不可用的样子。</td></tr><tr><td><code>keys</code></td><td><code>string[]</code></td><td></td><td>组合里的各枚键，如 <code>[&#39;Mod&#39;, &#39;S&#39;]</code>。 &#39;Mod&#39; 在 Mac 上是 ⌘、其余平台是 Ctrl；&#39;Shift&#39; / &#39;Alt&#39; / &#39;Ctrl&#39; / &#39;Meta&#39; 各自对应那一枚。 除修饰键外只能有一枚主键，多写的组合按不出来，也就永远不会命中。</td></tr><tr><td><code>onHotKey</code></td><td><code>(details: HotkeysTriggerDetails) =&gt; void</code></td><td></td><td>组合被按出来时的回调。</td></tr><tr><td><code>platform</code></td><td><code>HotkeysPlatform</code></td><td></td><td>按哪个平台的写法显示与解析。 缺省 &#39;auto&#39;：读 navigator 会在服务端渲染时炸，所以 headless 只认显式值， 由适配器挂载后测出来传进来；未落定前按非 Mac 出。</td></tr><tr><td><code>preventDefault</code></td><td><code>boolean</code></td><td></td><td>命中后拦下浏览器的默认动作，缺省开启（注册 Mod+S 就是为了不让浏览器弹保存）。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>target</code></td><td><code>HotkeysTarget</code></td><td></td><td>监听装在哪儿，缺省 &#39;document&#39;。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;HotkeysTranslations&gt;</code></td><td></td><td>读屏文案覆盖。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hot-key</code></td><td><code>HotkeysTriggerDetails</code></td><td>组合被按出来；detail 为 <code>{ keys: string[], event: KeyboardEvent }</code></td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>segments</code></td><td><code>readonly HotkeySegment[]</code></td><td>翻好的各枚键，顺序与 keys 一致；适配器照着它铺键帽。</td></tr><tr><td><code>platform</code></td><td><code>HotkeysResolvedPlatform</code></td><td>实际采用的平台写法。</td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td>监听当前是否生效。</td></tr><tr><td><code>target</code></td><td><code>HotkeysTarget</code></td><td>监听该装在哪儿，适配器据此挑节点。</td></tr><tr><td><code>separator</code></td><td><code>string</code></td><td>两枚键帽之间的连接符；Mac 的写法里键帽直接连排，此时是空串。</td></tr><tr><td><code>segmentOf</code></td><td><code>(value: string) =&gt; HotkeySegment | null</code></td><td>按 keys 里原样写的那个词取回这枚键；没有这枚键时为 null。</td></tr><tr><td><code>matches</code></td><td><code>(event: KeyboardEvent) =&gt; boolean</code></td><td>这次按键是否命中本组合（含输入法组合期与打字落点的排除）。</td></tr><tr><td><code>handleKeyDown</code></td><td><code>(event: KeyboardEvent) =&gt; void</code></td><td>适配器把它挂到监听节点的 keydown 上：命中即按 preventDefault 决定拦不拦，并回调 onHotKey。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getKeyProps</code></td><td><code>(props: HotkeysKeyProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/TR/uievents/#event-type-keydown" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>keys 指定的组合</code></td><td>enabled 未关，且不在输入法组合期</td><td>触发 onHotKey；preventDefault 开启（默认）时同时拦下浏览器的默认动作</td></tr><tr><td><code>keys 指定的组合</code></td><td>组合里没有 Ctrl / Meta / Alt，且按键落在输入框、文本域或可编辑区里</td><td>不触发也不拦：这类组合与打字撞车，输入优先</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>undefined | translations?.hotkey?.(names)</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>undefined | &#39;img&#39;</td></tr></tbody></table><ul><li>键帽整块对外是一张图（<code>role=&quot;img&quot;</code>），名字由 <code>aria-label</code> 给：读屏念不出 ⌘ ⇧ 这类符号，逐枚念出来也不成句。</li><li>每一枚键的读法与整句的拼法都可以经 <code>translations</code> 换掉，内建的是英文。</li><li><code>keys</code> 空着时不出 <code>role</code>：一张没有名字的图，读屏只念得出「图像」两个字。按数据渲染速查表时某行没有组合，这一格就是个空容器。</li><li>监听关掉后键帽只是转成暗底，字仍然读得出：这块是说明性文字而不是失效控件，用户此刻要认的正是这几枚键。</li><li>快捷键不能是唯一路径：它对应的动作必须另有一个看得见、点得到的入口。只有键盘组合的功能，触屏用户与只用指点设备的用户根本够不着。</li><li>不要占用浏览器与读屏已有的组合。读屏在浏览模式下会先吃掉大量单键，<code>Ctrl+W</code>、<code>Ctrl+T</code>、<code>F5</code> 这类浏览器组合也拦不住或拦了就是伤害。带 <code>Alt</code> 的组合在 Mac 上会改写字符输入，也要避开。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/hotkeys.css</code> 按部件选择：<code>[data-scope=&quot;hotkeys&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-platform</code></td><td>resolveHotkeysPlatform(props.platform)</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>key</code></td><td><code>data-modifier</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-hotkeys-fg</code> · <code>--xh-hotkeys-font-size</code> · <code>--xh-hotkeys-gap</code> · <code>--xh-hotkeys-key-bg</code> · <code>--xh-hotkeys-key-bg-disabled</code> · <code>--xh-hotkeys-key-border</code> · <code>--xh-hotkeys-key-fg</code> · <code>--xh-hotkeys-key-fg-modifier</code> · <code>--xh-hotkeys-key-font</code> · <code>--xh-hotkeys-key-font-weight</code> · <code>--xh-hotkeys-key-min-w</code> · <code>--xh-hotkeys-key-px</code> · <code>--xh-hotkeys-key-py</code> · <code>--xh-hotkeys-key-radius</code> · <code>--xh-hotkeys-key-shadow</code> · <code>--xh-hotkeys-separator-fg</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>挂在<a href="./menu">菜单</a>条目的右侧，或<a href="./button">按钮</a>旁边，标出这个动作的组合。</li><li>放进<a href="./dialog">对话框</a>里列一张速查表。</li><li>用<a href="./separator">分隔线</a>把速查表按功能分段。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>一律用 <code>Mod</code> 而不是写死 <code>Ctrl</code> 或 <code>Meta</code>：写死之后另一个平台上的用户看到的和按出来的对不上。</li><li>给单键组合（如 <code>?</code> 打开帮助）留一条别的入口，并注意它在输入区里不会触发。</li><li><code>target</code> 用 <code>parent</code> 把组合限制在一块面板内，避免整页范围的组合互相抢。</li><li>组合变了要同步改文档与提示，两处对不上比没有快捷键更糟。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>一屏里挂十几组全局组合：记不住，还必然和浏览器或读屏撞车。</li><li>用快捷键替代按钮：功能藏进组合里，等于对触屏用户不存在。</li><li>只把组合写在帮助页里，界面上不显示：用户不会为了一次操作去翻文档。</li></ul>',36))])}const q=i(n,[["render",p]]);export{g as __pageData,q as default};
